import pages as PG
from pages import *
from pages import foreword,glance,reading,story,cards,end,sources,build,covart,verse
from fx import *
PG.configure('/ganesha/festivals/ganesha-jayanti/',[('','Gaṇeśa Jayantī','His Winter Birthday in Māgha')],'red','Gaṇeśa Jayantī','Lord','Gaṇeśa Jayantī')
PG.CFG.update(backurl='/ganesha/festivals/',backname='Gaṇeśa festivals')
PG.OUT='outd/ganesha-jayanti/'
i=0
GA=lambda **k: ganesha(**k)
def tilladdu(): return laddu('#c9a06a')+''.join(f'<ellipse cx="{x}" cy="{y}" rx="2" ry="1.2" fill="#fff" stroke="none"/>' for x,y in [(-4,-6),(3,-9),(5,-3),(-2,-12)])
def peacock(): return '<ellipse cy="-14" rx="12" ry="8" fill="#1d6fb8"/><path d="M8 -18 q6 -14 4 -24" stroke="#1d6fb8" stroke-width="4" fill="none"/><path d="M-10 -14 q-30 -10 -34 -30 q20 0 34 22z" fill="#2a9d6f"/>'+''.join(f'<circle cx="{-30+k*6}" cy="{-30+k*3}" r="2.5" fill="#e0a800"/>' for k in range(4))
def seashore_temple(): return '<path d="M-60 0 q60 -10 120 0" fill="#8fb8de"/>'+g(0,-4,.6,palace())
COV=covart('Gaṇeśa in winter with a plate of sesame laddus, a lamp, and a seaside temple on the Konkan coast',f'<rect width="440" height="196" fill="#f6e3e1"/>'+'<path d="M0 170 q220 -16 440 0 v26 h-440z" fill="#8fb8de"/>'+g(360,160,1.1,palace())+g(190,170,1.6,GA())+g(80,186,1.5,plate())+g(70,174,1.1,tilladdu())+g(92,176,1.1,tilladdu())+g(290,186,1.6,lamp()))
pp=[foreword(i,['Most of India keeps Gaṇeśa’s birthday in the rains, on Bhādrapada’s Caturthī. Maharashtra, the Konkan coast and Goa keep another, in the cold of <b>Māgha</b>: <b>Gaṇeśa Jayantī</b>, the bright fourth of Māgha, which their tradition holds to be the birth itself. It comes wrapped in sesame and jaggery, and is quieter, more personal, without the crowds of the great festival.','This article explains why Gaṇeśa has more than one birthday, tells the Gaṇeśa Purāṇa’s stories of his avatāras born for the ages of the world, visits the Aṣṭavināyaka and the Konkan coast, and Karnataka’s own great Gaṇeśa shrines, and gives three verses for the day.'],[('z','Two birthdays?'),('b','Different traditions, Zappy. In the Konkan his birthday is in Māgha. The Marathi calendar actually counts three.')]),
 glance([('When','Māgha Śukla Caturthī; January–February'),('Names','Gaṇeśa Jayantī, Māghī Gaṇeśa, Tilakunda Caturthī, Varada Caturthī'),('Where','Above all Maharashtra, the Konkan and Goa'),('Belief','His true birthday in this tradition; Bhādrapada’s day his arrival or vow'),('Offerings','Til laḍḍus, modakas, dūrvā, red flowers'),('Texts cited','Gaṇeśa Purāṇa (avatāras for each yuga); Mudgala Purāṇa'),('Temples','Aṣṭavināyaka; Gaṇapatipuḷe; in Karnataka, Iḍagunji and Gōkarṇa')],svg(560,140,'Gaṇeśa with sesame laddus beside the sea',f'<rect width="560" height="140" fill="#f6e3e1"/>'+'<path d="M0 120 q280 -14 560 0 v20 h-560z" fill="#8fb8de"/>'+g(280,130,1.1,GA())+g(150,130,1.3,plate())+g(150,120,1,tilladdu())+g(450,124,.8,palace()))),
 reading('birthdays','WHICH IS THE BIRTHDAY?','Three Gaṇeśa days in one year',svg(560,160,'Three calendar markers: Bhādrapada, Māgha and Vaiśākha, each with a small Gaṇeśa',f'<rect width="560" height="160" fill="#fffaf0"/>'+''.join(g(x,120,.8,GA())+lab(x,145,t) for x,t in [(120,'Bhādrapada Śu. 4'),(280,'Māgha Śu. 4'),(440,'Vaiśākha Pūrṇimā')])),['<b>Bhādrapada.</b> Most of India keeps Bhādrapada Śukla Caturthī as Gaṇeśa’s birthday: the great festival of the rains (read our '+L('/ganesha/festivals/ganesha-chaturthi/','Gaṇeśa Caturthī')+' article).','<b>Māgha.</b> Maharashtrian tradition, citing the Gaṇeśa Purāṇa, often treats Bhādrapada’s day as a vow (vrata) and Māgha’s as the birth itself. Others say Bhādrapada marks his arrival on earth and Māgha his birth.','<b>Three.</b> The Marathi calendar counts three Gaṇeśa birthdays, including one in Vaiśākha in some traditions. We report the traditions without choosing.','<b>Every month.</b> Each bright Caturthī is a <b>Vināyaka Caturthī</b>, each dark one a '+L('/ganesha/festivals/sankashti-chaturthi/','Saṅkaṣṭī')+'. Gaṇeśa’s calendar is never empty.'],[('z','So which one is right?'),('b','Each tradition answers for itself, Zappy. Most of India picks Bhādrapada; the Konkan keeps Māgha.')],'More than one birthday <b>is fine</b>.'),
 story('mahotkata','MAHOTKAṬA, SON OF ADITI','The avatāra of the first age',strip('Three panels: two demon brothers terrorising the worlds; the child Mahotkaṭa born to Kaśyapa and Aditi; the ten-armed god on a lion defeating them',[panel([(demon(),.9),(demon('#6a2a2a'),.9)],'#fde4e4',150),panel([(sage('#ff8c1a'),.8),(person('#c0392b'),.8),(baby(),.6)],'#fff3cf',150),panel([(lion(),.7),(GA(seat=False),.7)],'#f6e3e1',150)],['Devāntaka and Narāntaka','born to Aditi','the lion rider']),'Gaṇeśa Purāṇa, Krīḍā Khaṇḍa, chs. 1–72 (as summarised in our '+L('/ganesha/forms/yuga-avatars/','four yuga avatāras')+' guide).',['In the Satya age two demon brothers, <b>Devāntaka</b> (“ender of gods”) and <b>Narāntaka</b> (“ender of men”), won great boons and terrorised the three worlds.','The gods prayed. Gaṇeśa was born as a child to the sage <b>Kaśyapa</b> and <b>Aditi</b>, and named <b>Mahotkaṭa Vināyaka</b>.','Even as a boy he destroyed the demons sent to kill him, one after another, in a series of adventures the Purāṇa tells at length.','Grown to his full form, ten-armed, red, riding a lion, he faced the two brothers and destroyed them.','The Māghī tradition connects Gaṇeśa’s birth to this kind of descent: God born as a child to set the world right.'],[('z','Ten arms and a lion?'),('b','The biggest form, Zappy, for the first and greatest age. The forms grow smaller as the ages decline.')],'Born <b>to set things right</b>.'),
 story('mayuresha','MAYŪREŚVARA','The peacock Gaṇeśa of Morgaon',strip('Three panels: the demon Sindhu with a pot of nectar in his belly; Gaṇeśa on a peacock; Gaṇeśa drawing the nectar out',[panel([(demon('#2a3a6a'),1),(pot('#e0a800'),.5)],'#e9e3f5',150),panel([(peacock(),1),(GA(seat=False),.6)],'#e3f5e9',150),panel([(GA(seat=False),.8),(demon('#2a3a6a'),.7),(pot('#e0a800'),.6)],'#fff3cf',150)],['Sindhu’s secret','the peacock rider','the nectar drawn out']),'Gaṇeśa Purāṇa, Krīḍā Khaṇḍa, chs. 73–126.',['In the Tretā age the demon <b>Sindhu</b> won immortality, held as a pot of nectar in his belly, and tormented the worlds.','Gaṇeśa was born to Śiva and Pārvatī as <b>Mayūreśvara</b>, six-armed and white, riding a peacock.','He fought Sindhu and drew the nectar out of his belly, and with it the demon’s power.','Morgaon, first of the eight Aṣṭavināyaka shrines, keeps him as <b>Moreśvar</b>, “lord of the peacock” (Marathi <i>mor</i>).','Popular tradition says he later gave the peacock to his brother Skanda, who still rides it.'],[('z','Gaṇeśa on a peacock?'),('b','In that age, yes, Zappy. And it’s why Morgaon’s Gaṇeśa is Moreśvar.')],'The peacock <b>lent to his brother</b>.'),
 verse('v-pancaratna','Gaṇeśa Pañcaratnam, verse 1','Holding the modaka with joy',['mudākarāttamodakaṃ sadāvimuktisādhakaṃ','kalādharāvataṃsakaṃ vilāsilokarakṣakam','anāyakaikanāyakaṃ vināśitebhadaityakaṃ','natāśubhāśunāśakaṃ namāmi taṃ vināyakam'],svg(200,150,'Gaṇeśa holding a modaka with a crescent moon on his head',f'<rect width="200" height="150" fill="#f6e3e1"/>'+g(100,140,1.3,GA())+g(100,36,.6,moon())+g(140,100,.9,modaka())),'I bow to Vināyaka, who holds the modaka in his hand with joy, who always brings liberation, who wears the crescent moon as an ornament, protector of the world at play, the one leader of those who have no leader, destroyer of the elephant-demon, who quickly destroys the misfortune of those who bow.',[('mudā','with joy'),('kara-ātta-modakam','modaka held in the hand'),('kalādhara-avataṃsakam','crowned with the crescent'),('anāyaka-eka-nāyakam','sole leader of the leaderless'),('vināśita-ibha-daityakam','slayer of the elephant-demon'),('natāśubha-āśu-nāśakam','quickly ending devotees’ misfortune')],'<b>Śaṅkara’s hymn.</b> The Gaṇeśa Pañcaratnam, attributed to Ādi Śaṅkara, is sung in Karnataka homes and temples on every Gaṇeśa day, Jayantī included. “Leader of those who have no leader” is one of the tenderest titles any god has.',k='The leader of <b>those with no leader</b>.',note='Text as on our '+L('/ganesha/hymns/ganesha-pancharatnam/','Gaṇeśa Pañcaratnam')+' page.'),
 reading('tila','TILAKUNDA CATURTHĪ','Sesame for the cold month',svg(560,160,'A plate of sesame laddus before Gaṇeśa, with a woollen shawl and a winter sun',f'<rect width="560" height="160" fill="#f6e3e1"/>'+'<rect y="135" width="560" height="25" fill="#e9c9c3"/>'+g(200,140,1.2,GA())+g(340,140,1.4,plate())+''.join(g(x,128,1.1,tilladdu()) for x in (320,345,368))+g(480,40,.8,sun(16))),['<b>Tila.</b> <i>Tila</i> is sesame, and the day is also called <b>Tilakunda Caturthī</b>: sesame and jaggery laḍḍus are offered to Gaṇeśa and shared; some bathe with sesame paste.','<b>The season.</b> Māgha is cold; sesame and jaggery are warming foods, which is why they also fill the plates at '+L('/festivals/makara-sankranti/','Makara Saṅkrānti')+' a few weeks earlier.','<b>Varada Caturthī.</b> The bright Caturthī is also called <b>Varada</b>, “boon-granting”: Gaṇeśa is worshipped as the giver of boons.','<b>The worship.</b> A clay or metal image at home, a day’s fast for some, modakas and til laḍḍus, dūrvā and red flowers; Gaṇeśa temples hold special worship, and some Mumbai neighbourhoods keep a small public Māghī Gaṇeśotsava.'],[('z','Why sesame?'),('b','It’s winter, Zappy. Sesame and jaggery warm you, and Gaṇeśa likes sweets anyway.')],'A birthday <b>wrapped in sesame</b>.'),
 cards('ashta','THE AṢṬAVINĀYAKA','Eight self-born Gaṇeśas around Pune',fig_row('Eight small Gaṇeśa shrines in a ring',[(palace(),.5)]*4,['Morgaon','Siddhaṭek','Pālī','Mahaḍ'],gy=150),[('🦚','Morgaon','Moreśvar, the peacock Gaṇeśa: the pilgrimage begins and ends here.'),('⛰️','Siddhaṭek and Pālī','Siddhivināyaka on the Bhīmā, where Viṣṇu is said to have worshipped him; Ballāḷeśvar at Pālī, named after a boy devotee.'),('🏞️','Mahaḍ, Theur, Lenyādri','Varadavināyaka; Cintāmaṇi; Girijātmaja in a Buddhist rock-cave.'),('🛕','Ojhar and Rāñjaṇgāv','Vighneśvara; Mahāgaṇapati, worshipped by Śiva before he fought Tripura.')],[('z','Eight Gaṇeśas in one trip?'),('b','A circuit of several hundred kilometres round Pune, Zappy. On Māghī Jayantī they’re all crowded. Read our '+L('/ganesha/temples/ashtavinayaka/','Aṣṭavināyaka')+' guide.')],'Eight shrines, <b>one circuit</b>.'),
 reading('konkan','THE KONKAN AND GOA','Where Māghī is strongest',svg(560,160,'A seaside temple at the foot of a hill on the Konkan coast',f'<rect width="560" height="160" fill="#e3f5e9"/>'+'<path d="M0 120 q280 -20 560 0 v40 h-560z" fill="#8fb8de"/>'+g(300,125,1.2,mountain('#7a9a6a',False))+g(300,112,.8,palace())),['<b>Gaṇapatipuḷe.</b> On the Ratnāgiri coast, the seaside temple of Gaṇapatipuḷe, whose self-born Gaṇeśa is called the <b>Paścima Dvāradevatā</b>, the western guardian god of India, keeps Māghī Jayantī as its great day; pilgrims walk round the hill that is held to be the god himself.','<b>Goa.</b> In Goa the day is kept with devotion in homes and the old temples of Ponda; Konkani families who also keep the great Bhādrapada festival mark Māghī quietly.','<b>Mumbai.</b> Some neighbourhoods hold Māghī Gaṇeśotsavas with public images for a day or more, a small echo of the rainy-season pandals.','<b>A family day.</b> Everywhere, the day is mainly for the home: one image, a lamp, laḍḍus, the Atharvaśīrṣa and the elders’ blessings.'],[('z','Gaṇeśa guards the west coast?'),('b','That’s Gaṇapatipuḷe’s title, Zappy: the western sentinel god of India.')],'The <b>western sentinel</b>.'),
 cards('karnataka','GAṆEŚA IN KARNATAKA','Shrines to visit on any Gaṇeśa day',fig_row('A coastal temple, a giant boulder Gaṇeśa, a hill and a lamp',[(palace(),.7),(GA(),1),(mountain(),.8),(lamp(),1.6)],['Iḍagunji','Hampi','Gōkarṇa','Bengaluru'],gy=150),[('🛕','Iḍagunji','On the Uttara Kannaḍa coast, the standing two-armed Vināyaka of '+L('/ganesha/temples/idagunji/','Iḍagunji')+', one of the most visited Gaṇeśa temples of the coast.'),('🪨','Hampi','The great monolithic Sāsivekāḷu and Kaḍalekāḷu Gaṇeśas among the ruins: see '+L('/ganesha/temples/hampi/','Hampi')+'.'),('🌊','Gōkarṇa','Where the boy Gaṇeśa tricked Rāvaṇa into setting down the Ātmaliṅga: see '+L('/ganesha/temples/gokarna/','Gōkarṇa')+'.'),('🏙️','Bengaluru','The Doḍḍa Gaṇapati of Basavanagudi, a huge boulder image covered in butter on special days: see '+L('/ganesha/temples/bengaluru-dodda-ganapati/','Doḍḍa Gaṇapati')+'.')],[('z','Do Karnataka temples keep Māghī?'),('b','Many hold special worship on every Vināyaka Caturthī, Zappy, Māgha’s included. The great crowds come in Bhādrapada.')],'Karnataka’s <b>own Gaṇeśas</b>.'),
 reading('gita','THE GAṆEŚA GĪTĀ','The teaching of Gajānana',svg(560,150,'Gaṇeśa teaching a seated king',f'<rect width="560" height="150" fill="#f6e3e1"/>'+'<rect y="125" width="560" height="25" fill="#e9c9c3"/>'+g(220,130,1.2,GA())+g(360,130,1,god('#7a3fa0'))+g(450,110,1.3,book())),['<b>The Dvāpara avatāra.</b> In the Dvāpara age Gaṇeśa came as <b>Gajānana</b>, four-armed on his mouse, to defeat the demon Sindūra; popular tradition says he smeared himself with the demon’s red, which is why sindūra is offered to him.','<b>The teaching.</b> To King <b>Vareṇya</b> he taught the <b>Gaṇeśa Gītā</b> (Gaṇeśa Purāṇa, Krīḍā Khaṇḍa 138–148), a Gāṇapatya counterpart of the Bhagavad Gītā on yoga, action and devotion, with Gaṇeśa as the supreme.','<b>The fourth.</b> In our own Kali age, the Purāṇa says, he will come as <b>Dhūmraketu</b>, two-armed, smoke-coloured, on a horse, at the end of the age.','<b>Why it fits.</b> A birthday is a good day to remember that the god is born again and again, in every age, as the need arises.'],[('z','Gaṇeśa has a Gītā too?'),('b','The Gāṇapatyas’ own, Zappy. Same idea as Kṛṣṇa’s: God teaches when a king is ready to listen.')],'Born <b>in every age</b>.'),
 verse('v-agajanana','Agajānana padmārkaṃ','The one-tusked lord of the mountain’s daughter',['agajānana padmārkaṃ gajānanam aharniśam','anekadaṃ taṃ bhaktānām ekadantam upāsmahe'],svg(200,150,'Pārvatī’s face shining on Gaṇeśa like the sun on a lotus',f'<rect width="200" height="150" fill="#f6e3e1"/>'+g(60,60,.9,sun(18))+g(120,140,1.2,GA())),'We worship day and night the elephant-faced one, who is a sun to the lotus that is the face of Pārvatī (the mountain-born), the one-tusked who gives much to his devotees.',[('aga-ja-ānana','the face of the mountain-born (Pārvatī)'),('padma-arkam','the sun to the lotus'),('ahar-niśam','day and night'),('anekadam','giver of many things'),('eka-dantam','the one-tusked'),('upāsmahe','we worship')],'<b>A word game.</b> The verse plays on <i>aneka</i> (many) and <i>eka</i> (one): the one-tusked who gives many gifts. And it puts the mother first: Gaṇeśa is the sun that makes Pārvatī’s face bloom like a lotus. A good birthday verse.',k='The one-tusked <b>who gives many gifts</b>.',note='Text as on our '+L('/ganesha/hymns/daily-slokas/','Gaṇeśa daily ślokas')+' page (verse 3).'),
 reading('meaning','WHAT THE DAY TEACHES','A quieter devotion',svg(560,150,'A single lamp before a small Gaṇeśa in a quiet room',f'<rect width="560" height="150" fill="#3a2a3a"/>'+g(280,130,1.2,GA())+g(380,130,1.8,lamp())+'<circle cx="380" cy="100" r="60" fill="#ffd60a" opacity=".1" stroke="none"/>'),['<b>Quiet.</b> Gaṇeśa Jayantī is devotion without crowds: one image, one lamp, a plate of sesame sweets, the family.','<b>Many answers.</b> The day is a reminder that Indian traditions can hold more than one answer, even to the question of a god’s birthday, without anyone being wrong.','<b>The season.</b> Its food and worship suit the weather, as Bhādrapada’s suit the rains: the festival follows the year.','<b>Return.</b> Gaṇeśa comes back in winter too. The remover of obstacles visits twice: once loudly, once softly.'],[('z','If I could do one thing for Gaṇeśa Jayantī?'),('b','Make a few til laḍḍus, Zappy, offer one to Gaṇeśa with the Pañcaratnam, and give the rest away.')],'In Māgha, <b>softly</b>.'),
 end(i,['<b>When.</b> Māgha Śukla Caturthī, January–February.','<b>Belief.</b> The birth itself, in Maharashtra, the Konkan and Goa.','<b>Stories.</b> Mahotkaṭa son of Aditi; Mayūreśvara; Gajānana and the Gaṇeśa Gītā.','<b>Customs.</b> Til laḍḍus, modakas, dūrvā; Pañcaratnam, Agajānana.','<b>Places.</b> Aṣṭavināyaka, Gaṇapatipuḷe; in Karnataka, Iḍagunji, Hampi, Gōkarṇa.'],'Previous: '+L('/ganesha/festivals/sankashti-chaturthi/','Saṅkaṣṭī Caturthī')+'. Next: '+L('/ganesha/temples/ashtavinayaka/','Temples: the Aṣṭavināyaka')+'.','Gaṇeśa Jayantī: the winter birthday'),
 sources([('Texts:','Gaṇeśa Purāṇa, Krīḍā Khaṇḍa (yuga avatāras; Gaṇeśa Gītā), as summarised in our yuga avatāras guide; Gaṇeśa Pañcaratnam and Agajānana verse from our own pages.'),('Customs:','Wikipedia, “Ganesh Jayanti” (date, names, Gaṇapatipuḷe); press sources on Māghī Gaṇeśotsava, Tilkund Caturthī and the three Marathi birthdays, and Goa, as summarised in our earlier guide; our Aṣṭavināyaka and Karnataka temple guides.')],'which day is the “true” birthday (traditions differ); the third, Vaiśākha birthday (varies); details of the yuga avatāras (summaries of the Purāṇa); the sindūra story (popular).','Interpretations are marked as such.')]
build(i,'MĀGHA CATURTHĪ · TILAKUNDA · THE KONKAN',COV,'Sesame for a winter birthday','Why Gaṇeśa has <b>more than one birthday</b>, the Gaṇeśa Purāṇa’s <b>avatāras</b>, sesame and the season, the <b>Aṣṭavināyaka</b>, the Konkan and Karnataka’s shrines, and three verses.','Gaṇeśa Jayantī explained: Māgha Śukla Caturthī as Gaṇeśa’s birthday in Maharashtra, the Konkan and Goa, the three Marathi birthdays, Mahotkaṭa and Mayūreśvara from the Gaṇeśa Purāṇa, Tilakunda Caturthī and sesame laddus, the Aṣṭavināyaka, Gaṇapatipuḷe, Karnataka’s Gaṇeśa shrines, the Gaṇeśa Gītā, Pañcaratnam and Agajānana verses.',pp)
print('gj ok',len(pp)+2)
